module uart_rx_from_ai(
	clk,
	rst_n,
	rx,
	out_flag,
	out_data);

	//---Ports declearation: generated by Robei---
	input clk;
	input rst_n;
	input rx;
	output out_flag;
	output [7:0] out_data;

	wire clk;
	wire rst_n;
	wire rx;
	reg out_flag;
	reg [7:0] out_data;

	//----Code starts here: integrated by Robei-----
	//常量化波特率，可更改
	parameter	BPS=9600;					//波特率9600bps，可更改
	parameter	clk_FRE=33_000_000;		//
	localparam	BPS_CNT='d6;	//传输一位数据所需要的时钟个数 BPS_CNT=clk_FRE/BPS,为便于仿真，我们设置为
	 
	reg 			uart_rx_d0;		//寄存1拍
	reg 			uart_rx_d1;		//寄存2拍
	reg [15:0]		clk_cnt;				//时钟计数器
	reg [3:0]		rx_cnt;					//接收计数器
	reg 			rx_flag;				//接收标志位
	reg [7:0]		out_data_reg;		//数据寄存
		
	wire 			neg_out_data;		//数据的下降沿
	 
	assign	neg_out_data=uart_rx_d1 & (~uart_rx_d0);  //捕获数据线的下降沿，用来标志数据传输开始
	//将数据线打两拍，作用1：同步不同时钟域信号，防止亚稳态；作用2：用以捕获下降沿
	always@(posedge clk or negedge rst_n)begin
		if(!rst_n)begin
			uart_rx_d0<=1'b0;
			uart_rx_d1<=1'b0;
		end
		else begin
			uart_rx_d0<=rx;
			uart_rx_d1<=uart_rx_d0;
		end		
	end
	//捕获到数据下降沿（起始位0）后，拉高传输开始标志位，并在第9个数据（终止位）的传输过程正中（数据比较稳定）再将传输开始标志位拉低，标志传输结束
	always@(posedge clk or negedge rst_n)begin
		if(!rst_n)
			rx_flag<=1'b0;
		else begin 
			if(neg_out_data)
				rx_flag<=1'b1;
			else if((rx_cnt==4'd9)&&(clk_cnt==BPS_CNT/2))//在第9个数据（终止位）的传输过程正中（数据比较稳定）再将传输开始标志位拉低，标志传输结束
				rx_flag<=1'b0;
			else 
				rx_flag<=rx_flag;			
		end
	end
	//时钟每计数一个BPS_CNT（传输一位数据所需要的时钟个数），即将数据计数器加1，并清零时钟计数器
	always@(posedge clk or negedge rst_n)begin
		if(!rst_n)begin
			rx_cnt<=4'd0;
			clk_cnt<=16'd0;
		end
		else if(rx_flag)begin
			if(clk_cnt<BPS_CNT-1'b1)begin
				clk_cnt<=clk_cnt+1'b1;
				rx_cnt<=rx_cnt;
			end
			else begin
				clk_cnt<=16'd0;
				rx_cnt<=rx_cnt+1'b1;
			end
		end
		else begin
			rx_cnt<=4'd0;
			clk_cnt<=16'd0;
		end		
	end
	//在每个数据的传输过程正中（数据比较稳定）将数据线上的数据赋值给数据寄存器
	always@(posedge clk or negedge rst_n)begin
		if(!rst_n)
			out_data_reg<=8'd0;
		else if(rx_flag)
			if(clk_cnt==BPS_CNT/2) begin
				case(rx_cnt)			
					4'd1:out_data_reg[0]<=rx;
					4'd2:out_data_reg[1]<=rx;
					4'd3:out_data_reg[2]<=rx;
					4'd4:out_data_reg[3]<=rx;
					4'd5:out_data_reg[4]<=rx;
					4'd6:out_data_reg[5]<=rx;
					4'd7:out_data_reg[6]<=rx;
					4'd8:out_data_reg[7]<=rx;
					default:;
				endcase
			end
			else
				out_data_reg<=out_data_reg;
		else
			out_data_reg<=8'd0;
	end	
	//当数据传输到终止位时，拉高传输完成标志位，并将数据输出
	always@(posedge clk or negedge rst_n)begin
		if(!rst_n)begin
			out_flag<=1'b0;
			out_data<=8'd0;
		end	
		else if(rx_cnt==4'd9)begin
			out_flag<=1'b1;
			out_data<=out_data_reg;
		end		
		else begin
			out_flag<=1'b0;
			out_data<=8'd0;
		end
	end
	
endmodule    //uart_rx_from_ai

